export const gallbladderIdeas: IdeaInput[] = [
  idea({ id: IDEAS.separate, name: "Report gallbladder cancer as its own population in every biliary trial", maturity: "speculative", actor: "regulator", cost: "small", horizonYears: 3,
    tldr: "Every drug gallbladder cancer patients receive was tested in mixed bile duct trials where they were a subgroup. Requiring trials to pre-specify and publish gallbladder results, with a minimum number enrolled, would give the disease its own evidence at almost no cost.",
    summary: "ABC-02, BILCAP, ABC-06, TOPAZ-1 and KEYNOTE-966 enrolled gallbladder cancer alongside intrahepatic and extrahepatic cholangiocarcinoma and reported it, if at all, in forest plots. Yet the diseases differ: HER2 positivity runs at 9 to 20 percent in gallbladder and extrahepatic cancers against 5 percent intrahepatic; immune profiles differ by population; and the UK CAPBIL cohort saw no adjuvant benefit in a mostly gallbladder population. A reporting standard (pre-specified gallbladder stratum, minimum enrolment, mandatory subgroup publication) could be asked of sponsors by regulators and journals and would cost the trials almost nothing.",
    hypothesis: "Mandating a pre-specified gallbladder cancer stratum with published results in biliary tract cancer trials will reveal clinically meaningful differences in treatment effect between gallbladder cancer and cholangiocarcinoma within five years.",
    rationale: "Prevalence of HER2, immune profile and recurrence pattern already differ between sites; pooled analyses hide effect modification. The cost of a stratum is small; the cost of a wrong extrapolation is borne by every gallbladder patient.",
    test: "Retrospective: obtain gallbladder-stratum results from TOPAZ-1, KEYNOTE-966, BILCAP and ABC-06 and test for interaction with site. Prospective: ACTICCA-1 and ARTEMIDE-Biliary01 publish gallbladder strata as primary-paper tables.",
    cancers: [GB, "biliary-tract-cancer"], trials: ["topaz-1", "keynote-966", "bilcap", "abc-06", "acticca-1", "nct06109779"], terms: ["hazard-ratio"], bottlenecks: ["b-rare-cancers", "b-trial-design", "b-negative-results"], keyPapers: ["paper-galdy-her2-biliary-tract-meta-analysis-cancer-metastasis-rev-2017", "paper-zhu-population-specific-immunogenomics-gallbladder-cancer-mod-pathol-2025", "paper-mcclements-capbil-surgical-outcomes-gallbladder-cancer-hpb-2026"],
    links: [epmc("27981460", "Galdy et al.: HER2 in biliary tract cancers by site (Cancer Metastasis Rev 2017)"), epmc("40541865", "Zhu et al.: population-specific immunogenomics of gallbladder cancer (Mod Pathol 2025)")] }),
  idea({ id: IDEAS.pathway, name: "A national incidental gallbladder cancer pathway: histology for every gallbladder, referral within two weeks, re-resection by eight", maturity: "early-clinical", actor: "clinic", cost: "small", horizonYears: 4,
    tldr: "About six in every thousand gallbladders removed for stones contain cancer. A written pathway that sends every specimen to the pathologist, refers every T1b or deeper cancer to a liver surgeon within two weeks and books the second operation within eight would turn a lottery into a system.",
    summary: "Incidental cancer is 0.6 percent of cholecystectomies (Pyo 2020). In the Netherlands only 24 percent of eligible patients were re-resected (2020); in the UK CAPBIL cohort 67.7 percent had liver resection (2026), with the reasons for the rest unknown. Observational data favour re-resection at four to eight weeks (Ethun 2017) though a 2026 individual patient data meta-analysis found timing did not change survival, so the pathway should prioritise completion over speed. Selective histology policies risk missing cancers (Khan 2021 systematic review). A national pathway with audit, the model the NHS uses for other two-week-wait cancers, needs no new drug and could be measured through existing registries.",
    hypothesis: "A mandated pathway (routine histology, two-week referral of T1b or deeper incidental cancers to a hepatobiliary multidisciplinary team, re-resection within eight weeks where fit) will raise the proportion of eligible patients re-resected to above 80 percent and be associated with longer disease-free survival at national level.",
    rationale: "The intervention with the largest observed survival association in incidental gallbladder cancer is completing the radical operation; the largest documented failure is not reaching it.",
    test: "Stepped-wedge implementation across hepatobiliary networks with registry-linked outcomes (re-resection rate, interval, R0 rate, disease-free survival), benchmarked against the CAPBIL 2014 to 2022 baseline.",
    cancers: [GB], terms: ["incidental-gallbladder-cancer", "radical-cholecystectomy"], trials: ["opt-in"], bottlenecks: ["b-care-fragmentation", "b-knowledge-diffusion"], keyPapers: ["paper-pyo-incidental-gallbladder-cancer-meta-analysis-jcm-2020", "paper-de-savornin-lohman-re-resection-incidental-gallbladder-cancer-aso-2020", "paper-mcclements-capbil-incidental-gallbladder-cancer-bjs-2026", "paper-ethun-re-resection-timing-incidental-gallbladder-cancer-jama-surg-2017", "paper-selvakumar-revision-surgery-timing-ipd-meta-analysis-hpb-2026"],
    links: [epmc("31741109", "de Savornin Lohman et al.: re-resection rate 24 percent in the Netherlands (Ann Surg Oncol 2020)"), epmc("42013358", "CAPBIL: 67.7 percent liver resection across 24 UK centres (Br J Surg 2026)"), epmc("33773526", "Khan et al.: selective versus routine histology of cholecystectomy specimens, systematic review (Asian Pac J Cancer Prev 2021)")] }),
  idea({ id: IDEAS.t1b, name: "Test whether T1b gallbladder cancer needs the second operation at all", maturity: "early-clinical", actor: "research", cost: "medium", horizonYears: 8,
    tldr: "Guidelines send everyone whose chance-found gallbladder cancer has just reached the muscle layer back for liver and lymph node surgery, yet the largest international series found 95 in 100 alive without the disease at five years whether or not they had it. A prospective study could spare thousands of operations, or confirm they are needed.",
    summary: "In 237 T1b patients from 14 centres in Korea, Japan, Chile and the United States, five-year disease-specific survival was 93.7 percent after simple cholecystectomy and 95.5 percent after extended cholecystectomy (p=0.496), with no difference by nodes or location (Kim 2018). Pawlik's series found no liver residual disease in T1 tumours but nodal metastasis in 12.5 percent. The evidence is retrospective and confounded by selection, and T1b itself is hard to standardise on pathology. A prospective registry with central pathology review, or a non-inferiority trial of observation with imaging surveillance against extended cholecystectomy, is the missing study.",
    hypothesis: "In T1b gallbladder cancer with negative cystic duct margin and no perforation, simple cholecystectomy with surveillance is non-inferior to extended cholecystectomy for five-year disease-specific survival, with a margin of 5 percentage points.",
    rationale: "Observed five-year disease-specific survival above 93 percent in both arms leaves little room for benefit; extended cholecystectomy carries operative risk and cost in an elderly population.",
    test: "International prospective registry with central pathology and pre-specified comparison, or a randomised non-inferiority trial (about 600 patients for a 5-point margin at 94 percent baseline) with nodal sampling as a secondary randomisation.",
    cancers: [GB], terms: ["radical-cholecystectomy", "incidental-gallbladder-cancer", "tnm-staging", "de-escalation"], bottlenecks: ["b-trial-design", "b-surgery-radiation-innovation"], keyPapers: ["paper-kim-t1b-gallbladder-cancer-international-jhbps-2018", "paper-pawlik-incidental-gallbladder-cancer-residual-disease-jgs-2007"],
    links: [epmc("30562839", "Kim et al.: optimal surgical treatment of T1b gallbladder cancer, 14 centres (J Hepatobiliary Pancreat Sci 2018)")] }),
  idea({ id: IDEAS.t2a, name: "A trial of sparing the liver resection in peritoneal-side (T2a) gallbladder cancer", maturity: "early-clinical", actor: "research", cost: "medium", horizonYears: 8,
    tldr: "Muscle-invading gallbladder tumours on the free side of the organ recur in the liver far less often than those against it. Two meta-analyses found the liver resection helped only the liver-side group, so a randomised trial could test dropping it for the free side.",
    summary: "Shindoh (2015) showed liver recurrence of 3 percent for peritoneal-side against 23 percent for hepatic-side T2 tumours; Kang's meta-analysis (1,789 patients) found no survival difference between extended and simple cholecystectomy in T2a (odds ratio 0.802) and Khan's (2,345 patients) found liver resection improved survival only in T2b. Lymphadenectomy would be retained because T2a nodal metastasis is still 27 percent. Reproducible assignment of side on pathology is the practical obstacle and would need a central review protocol.",
    hypothesis: "In T2a gallbladder cancer, cholecystectomy with portal lymphadenectomy but without liver bed resection is non-inferior to extended cholecystectomy for five-year recurrence-free survival.",
    rationale: "The liver bed is the target of the resection and the liver is rarely the site of recurrence in T2a; nodes remain a risk and are retained in the experimental arm.",
    test: "Randomised non-inferiority trial with central pathology confirmation of side, stratified by incidental versus suspected presentation; recurrence-free survival primary, liver-specific recurrence and morbidity secondary.",
    cancers: [GB], terms: ["t2a-versus-t2b", "radical-cholecystectomy", "lymphadenectomy", "de-escalation"], bottlenecks: ["b-surgery-radiation-innovation", "b-trial-design"], keyPapers: ["paper-shindoh-t2-gallbladder-cancer-tumour-location-ann-surg-2015", "paper-kang-t2-gallbladder-cancer-location-meta-analysis-jcm-2021", "paper-khan-t2-gallbladder-cancer-liver-resection-meta-analysis-updates-surg-2021", "paper-lee-t2-gallbladder-cancer-surgical-strategy-aso-2015"],
    links: [epmc("34362101", "Kang et al.: prognostic significance of tumour location in T2 gallbladder cancer, meta-analysis (J Clin Med 2021)"), epmc("34426958", "Khan et al.: tumour location and liver resection in T2 gallbladder cancer, meta-analysis (Updates Surg 2021)")] }),
  idea({ id: IDEAS.her2, name: "Reflex HER2 testing of every advanced gallbladder and extrahepatic biliary cancer", maturity: "early-clinical", actor: "clinic", cost: "small", horizonYears: 2,
    tldr: "Between one in eleven and one in five gallbladder cancers is HER2-positive and two HER2 drugs are now approved, but testing still happens only when someone asks. Making it automatic on every advanced biliary diagnosis, on resection tissue where it exists, would find the patients the trials were built for.",
    summary: "HER2 overexpression is about 20 percent in extrahepatic biliary cancers in the 2017 meta-analysis and 9.4 percent of gallbladder cancers by the HERIZON-BTC-01 definition in a 2026 resected series, which also found frequent heterogeneity involving under half of tumour cells, so small biopsies can miss it. Zanidatamab produced a 41.3 percent response rate in HER2-positive disease and trastuzumab deruxtecan has a tumour-agnostic HER2 3+ indication. Testing uptake in biliary cancer is not routinely audited. Reflex immunohistochemistry with in situ hybridisation for 2+ cases, ordered by pathology at diagnosis, is the model used for gastric and breast cancer.",
    hypothesis: "Pathology-initiated reflex HER2 testing at diagnosis of advanced gallbladder or extrahepatic biliary cancer will raise the tested fraction to above 90 percent and double the number of patients receiving HER2-directed therapy within two years.",
    rationale: "The drugs exist and are approved; the bottleneck is a test that is cheap, standardised and already run in every pathology laboratory for other cancers.",
    test: "Before-and-after audit across a hepatobiliary network: proportion tested, turnaround time, HER2-positive rate, proportion of positives treated, with a heterogeneity sub-study comparing biopsy and resection specimens.",
    cancers: [GB, "extrahepatic-cholangiocarcinoma"], targets: ["her2"], drugs: ["zanidatamab", "trastuzumab-deruxtecan"], trials: ["herizon-btc-01", "herizon-btc-302", "destiny-pantumor02"], terms: ["her2-positive", "ihc", "fish"], bottlenecks: ["b-biomarker-validation", "b-knowledge-diffusion"], keyPapers: ["paper-galdy-her2-biliary-tract-meta-analysis-cancer-metastasis-rev-2017", "paper-angerilli-her2-ihc-cish-biliary-hum-pathol-2026", "paper-harding-lancet-oncol"],
    links: [epmc("42595189", "Angerilli et al.: HER2 status and heterogeneity in 140 resected biliary cancers (Hum Pathol 2026)"), epmc("37276871", "HERIZON-BTC-01 (Lancet Oncol 2023)")] }),
  idea({ id: IDEAS.screen, name: "Risk-targeted ultrasound screening in high-incidence regions, tested against usual care", maturity: "speculative", actor: "policy", cost: "medium", horizonYears: 10,
    tldr: "In parts of Chile and northern India gallbladder cancer is common enough that a cheap ultrasound programme aimed at the highest-risk people might catch it while surgery can still cure it. Nobody has run the trial.",
    summary: "Sixty percent of Tata Memorial's 1,950 gallbladder cancer patients arrived with metastases and only 16 percent could be treated for cure; median survival was 58.2 months for early-stage against 4.2 months for metastatic disease. Risk is concentrated by geography (the Gangetic belt; southern Chile), ancestry (Mapuche), sex, gallstones and typhoid carriage, which makes a targeted rather than population programme plausible. Ultrasound is cheap and available. The risks are overdiagnosis of polyps and over-treatment of stones, which the Kaiser Permanente cohort shows are real in low-incidence settings; a high-incidence setting changes the arithmetic and only a randomised or cluster trial can show whether deaths fall.",
    hypothesis: "In districts with age-standardised gallbladder cancer incidence above 10 per 100,000, a risk-scored ultrasound screening programme for women aged 40 to 65 with gallstones or other risk factors will shift stage at diagnosis and reduce gallbladder cancer mortality by 20 percent within ten years.",
    rationale: "Stage at diagnosis is the dominant determinant of survival; incidence in the target populations is high enough for a positive predictive value that low-incidence settings cannot reach.",
    test: "Cluster-randomised trial by district in Bihar or Uttar Pradesh and southern Chile, with usual care control, primary endpoint gallbladder cancer mortality at ten years, secondary endpoints stage distribution, cholecystectomy rate and overdiagnosis.",
    cancers: [GB], technologies: ["ultrasound"], terms: ["screening", "overdiagnosis", "gallbladder-polyp", "prophylactic-cholecystectomy"], institutions: ["tata-memorial"], bottlenecks: ["b-early-detection", "b-global-access", "b-overdiagnosis"], keyPapers: ["paper-patkar-tata-memorial-gallbladder-cancer-registry-cancer-epidemiol-2025", "paper-dutta-gallbladder-cancer-epidemiology-india-chin-clin-oncol-2019", "paper-szpakowski-gallbladder-polyps-20-year-cohort-jama-netw-open-2020", "paper-roa-gallbladder-cancer-primer-nat-rev-dis-primers-2022"],
    links: [epmc("41237686", "Patkar et al.: Tata Memorial gallbladder cancer registry, 60 percent metastatic at presentation (Cancer Epidemiol 2025)"), epmc("31484488", "Dutta et al.: epidemiology of gallbladder cancer in India (Chin Clin Oncol 2019)")] }),
  idea({ id: IDEAS.chile, name: "Redesign Chile's prophylactic cholecystectomy programme around risk, and evaluate it properly", maturity: "being-tested-at-scale", actor: "policy", cost: "large", horizonYears: 10,
    tldr: "Chile has paid for preventive gallbladder removal in 35 to 49 year olds with stones since 2006 without a design that can show whether it prevents cancer deaths. Targeting the operation by region, ancestry and risk score, with an evaluation built in, would answer the question the world's only such programme has left open for twenty years.",
    summary: "The GES programme has issued 284,139 notifications since 2006. Standardised gallbladder cancer mortality has fallen, but was falling before the programme, and the 2019 analysis found the targeted age group's mortality decline doubled (4 to 8 percent per period) without a national break in trend. High-incidence areas do not receive proportionally more operations. Genetic work shows Mapuche ancestry raises risk independently of stones and body mass index, and exome studies show Chilean tumours carry the lowest mutation burden of five countries studied. A risk-based redesign (region, ancestry-informed score, sex, typhoid history) with a stepped-wedge or regression-discontinuity evaluation would make the programme both more efficient and, for the first time, measurable.",
    hypothesis: "Reallocating GES cholecystectomy capacity to a validated risk score rather than an age band will reduce gallbladder cancer mortality per operation performed by at least 30 percent, and a built-in stepped-wedge rollout will detect that effect within ten years.",
    rationale: "The programme's marginal benefit is highest where incidence and individual risk are highest; current allocation by age alone ignores both.",
    test: "Stepped-wedge rollout of the risk-based allocation across health service regions, with gallbladder cancer mortality and incidence from national statistics as primary outcomes and operations per prevented death as the efficiency measure.",
    cancers: [GB], terms: ["prophylactic-cholecystectomy", "screening"], institutions: ["falp-chile", "nci"], bottlenecks: ["b-prevention-adoption", "b-real-world-evidence"], keyPapers: ["paper-samaniego-chile-ges-programme-evaluation-rev-med-chile-2024", "paper-mardones-frenz-chile-ges-mortality-rev-med-chile-2019", "paper-cid-chile-programme-gallbladder-cancer-mortality-am-j-epidemiol-2024", "paper-garate-calderon-gallbladder-cancer-worldwide-exome-ebiomedicine-2026"],
    links: [epmc("40052976", "Samaniego et al.: is it time to modify the GES programme (Rev Med Chile 2024)"), epmc("37627062", "Zollner et al.: Mapuche ancestry and gallbladder cancer risk, instrumental variable analysis (Cancers 2023)")] }),
  idea({ id: IDEAS.typhi, name: "Cholecystectomy or ultrasound surveillance for chronic typhoid carriers in endemic regions", maturity: "speculative", actor: "policy", cost: "medium", horizonYears: 8,
    tldr: "People who carry the typhoid bacterium in their gallbladder long term have about four times the usual risk of gallbladder cancer. Two meta-analyses suggest offering them gallbladder removal or regular scans; no programme has tried it.",
    summary: "Chronic Salmonella Typhi carriage carried a pooled odds ratio of 4.28 across 17 studies (Nagaraja and Eslick 2014) and a summary relative risk of 4.6 to 5.0 in the Chilean case-control study and meta-analysis (Koshiol 2016), with the gallbladder as the reservoir of carriage. The carrier state is diagnosable by stool culture or Vi serology and cholecystectomy is also the treatment for carriage itself. A pragmatic programme in a typhoid-endemic, gallbladder-cancer-endemic region (northern India) could randomise identified carriers to cholecystectomy or annual ultrasound and measure cancer incidence, with the added public health benefit of removing a transmission reservoir.",
    hypothesis: "Offering cholecystectomy to confirmed chronic S. Typhi carriers aged 40 to 65 in high-incidence districts will reduce gallbladder cancer incidence in that group by at least half over ten years compared with surveillance alone.",
    rationale: "A fourfold relative risk on a high baseline incidence gives an absolute risk large enough to justify an operation that also cures carriage.",
    test: "Two-arm pragmatic randomised trial (cholecystectomy vs annual ultrasound) in identified carriers, primary endpoint gallbladder cancer incidence at ten years, secondary endpoints typhoid transmission and surgical morbidity; a preceding screening study to establish carrier prevalence and Vi serology performance.",
    cancers: [GB], terms: ["prophylactic-cholecystectomy", "screening", "inflammation"], bottlenecks: ["b-prevention-adoption", "b-global-access"], keyPapers: ["paper-nagaraja-eslick-typhi-carrier-gallbladder-cancer-meta-analysis-apt-2014", "paper-koshiol-salmonella-typhi-gallbladder-cancer-cancer-med-2016"],
    links: [epmc("24612190", "Nagaraja and Eslick: chronic S. Typhi carrier state and gallbladder cancer, meta-analysis (Aliment Pharmacol Ther 2014)"), epmc("27726295", "Koshiol et al.: S. Typhi and gallbladder cancer, case-control and meta-analysis (Cancer Med 2016)")] }),
  idea({ id: IDEAS.mrd, name: "A ctDNA residual disease-guided adjuvant trial after gallbladder cancer resection", maturity: "early-clinical", actor: "research", cost: "medium", horizonYears: 6,
    tldr: "After surgery for bile duct or gallbladder cancer, a blood test for leftover tumour DNA picks out the people whose cancer will return with hazard ratios of 16 to 26 in two recent cohorts. Nobody has yet tested giving those people more than the standard capecitabine.",
    summary: "Tumour-informed ctDNA in the 2 to 12 week window after biliary resection was positive in 23 percent of 167 patients and carried a relapse-free survival hazard ratio of 15.86 (Malla 2026); in a 56-patient cohort the hazard ratio was 26 (Yu 2025). Gallbladder cancer recurs early and distantly after re-resection (Varshney 2025), which is the setting where a residual disease test could pick who gets escalation. The template exists in colon and bladder cancer (DYNAMIC, IMvigor011). A biliary trial would randomise ctDNA-positive patients after resection to capecitabine or gemcitabine-cisplatin with durvalumab, and could de-escalate ctDNA-negative T1b or T2a patients to observation.",
    hypothesis: "In resected gallbladder cancer with detectable ctDNA at 4 to 8 weeks, adjuvant gemcitabine-cisplatin plus durvalumab improves two-year recurrence-free survival over capecitabine by at least 15 percentage points; in ctDNA-negative early-stage disease, observation is non-inferior to capecitabine.",
    rationale: "Residual disease positivity is the strongest prognostic factor yet measured after biliary resection, and stronger than CA 19-9; adjuvant capecitabine's benefit is unproven in gallbladder cancer specifically.",
    test: "Two-cohort randomised trial (escalation in ctDNA-positive, de-escalation in ctDNA-negative) nested in a national incidental cancer pathway, with tumour-informed assay from the resection specimen; about 400 patients over four years across a hepatobiliary network.",
    cancers: [GB, "biliary-tract-cancer"], technologies: ["liquid-biopsy", "mrd-testing"], drugs: ["signatera", "capecitabine", "gemcitabine-cisplatin", "durvalumab"], terms: ["ctdna", "mrd", "neoadjuvant-adjuvant", "de-escalation"], trials: ["bilcap", "acticca-1"], bottlenecks: ["b-dormancy-mrd", "b-trial-design"], keyPapers: ["paper-malla-ctdna-resected-biliary-tract-cancer-esmo-gi-onc-2026", "paper-yu-ctdna-early-recurrence-biliary-tract-cancer-jco-po-2025"], related: ["ctdna-tests", "idea-btc-ctdna-fgfr-resistance"],
    links: [epmc("42583118", "Malla et al.: real-world ctDNA after resection of stage I to III biliary tract cancer (ESMO GI Oncol 2026)"), epmc("39772829", "Yu et al.: ctDNA and early recurrence after biliary resection (JCO Precis Oncol 2025)")] }),
  idea({ id: IDEAS.neo, name: "Chemotherapy before the second operation for high-risk incidental gallbladder cancer", maturity: "being-tested-at-scale", actor: "research", cost: "medium", horizonYears: 4,
    tldr: "Gallbladder cancers found by chance often come back within six months of the second operation, usually far from the gallbladder, which suggests the disease was already in the bloodstream. Two randomised trials are testing chemotherapy first; one closed small, the other reports in 2028.",
    summary: "Most recurrences after radical re-resection are distant and early (Varshney 2025). GAIN (Germany, three cycles of gemcitabine-cisplatin before and after surgery) closed in October 2024 with 68 of 333 planned patients; OPT-IN (ECOG-ACRIN, phase 2/3, 186 estimated) randomises T2 to T3 incidental cancer to perioperative or adjuvant chemotherapy with an estimated primary completion of July 2028. Neoadjuvant treatment also selects out patients who progress during chemotherapy and would not have benefited from a major operation. The regimen question has moved on: TOPAZ-1 makes gemcitabine-cisplatin-durvalumab the natural perioperative arm for the next trial.",
    hypothesis: "In T2b, T3 or node-positive incidental gallbladder cancer, three cycles of gemcitabine-cisplatin (with or without durvalumab) before re-resection improves three-year overall survival over re-resection followed by adjuvant therapy.",
    rationale: "Early distant recurrence argues for systemic treatment before a morbid operation; the approach is standard in gastric and pancreatic cancer.",
    test: "OPT-IN's readout (2028) for chemotherapy alone; a successor trial adding durvalumab to the perioperative arm, stratified by T2a/T2b and nodes, run through the national incidental cancer pathway.",
    cancers: [GB], trials: ["opt-in", "gain-igbc", "topaz-1"], drugs: ["gemcitabine-cisplatin", "durvalumab"], terms: ["incidental-gallbladder-cancer", "neoadjuvant-adjuvant", "radical-cholecystectomy"], institutions: ["krankenhaus-nordwest"], companies: ["ecog-acrin"], bottlenecks: ["b-trial-enrolment", "b-trial-design"], keyPapers: ["paper-varshney-neoadjuvant-incidental-gallbladder-cancer-systematic-review-ahbps-2025", "paper-gain-trial-protocol-bmc-cancer-2020"],
    links: [epmc("40064481", "Varshney et al.: neoadjuvant treatment for incidental gallbladder cancer, systematic review (Ann Hepatobiliary Pancreat Surg 2025)"), ct("NCT04559139"), ct("NCT03673072")] }),
  idea({ id: IDEAS.rt, name: "A randomised trial of adjuvant chemoradiation after margin-positive or node-positive gallbladder cancer resection", maturity: "early-clinical", actor: "research", cost: "medium", horizonYears: 8,
    tldr: "Radiotherapy after gallbladder cancer surgery rests on one 79-patient trial with no comparison arm and a US insurance database. People whose surgery left cancer at the edge or in the nodes are the ones it might help, and they have never been randomised.",
    summary: "SWOG S0809 gave chemotherapy then chemoradiation to 79 patients after resection with pT2 to 4, node-positive or margin-positive disease: two-year survival was 65 percent and no worse after R1 (60 percent) than R0 (67 percent) resection. Wang's SEER-Medicare nomogram (1,137 patients) predicts benefit for T2 or N1 or worse, and the NCDB validation found radiotherapy associated with lower mortality in T2 to T4 disease. NCCN lists chemoradiation as an option; the UK does not routinely offer it. POLCAGB tests radiotherapy before surgery in locally advanced disease, but the adjuvant R1 or node-positive question, where local recurrence is a real fraction of failures (14 local, 9 combined of 47 relapses in S0809), has no randomised trial.",
    hypothesis: "After R1 or node-positive resection of gallbladder cancer, capecitabine-based chemoradiation added to adjuvant systemic therapy improves three-year locoregional recurrence-free survival by at least 15 percentage points without reducing overall survival.",
    rationale: "Local recurrence contributes to about half of relapses after margin-positive resection in the only prospective series; modern conformal radiotherapy has lower toxicity than the regimens of the SEER era.",
    test: "Randomised phase 2/3 of adjuvant systemic therapy with or without capecitabine-based chemoradiation in R1 or N+ gallbladder cancer, locoregional recurrence-free survival primary in phase 2 and overall survival in phase 3; about 300 patients, feasible only as an international cooperative-group trial.",
    cancers: [GB], trials: ["swog-s0809", "polcagb", "bilcap"], drugs: ["capecitabine"], terms: ["chemoradiation", "radiotherapy", "neoadjuvant-adjuvant"], technologies: ["sbrt"], institutions: ["tata-memorial"], companies: ["swog"], bottlenecks: ["b-surgery-radiation-innovation", "b-trial-enrolment"], keyPapers: ["paper-swog-s0809-adjuvant-chemoradiation-jco-2015", "paper-wang-adjuvant-chemoradiotherapy-nomogram-gallbladder-cancer-jco-2011", "paper-giannis-ajcc8-gallbladder-staging-validation-cancers-2021"],
    links: [epmc("25964250", "SWOG S0809 (J Clin Oncol 2015)"), epmc("22067404", "Wang et al.: nomogram for adjuvant chemoradiotherapy benefit in resected gallbladder cancer (J Clin Oncol 2011)")] }),
  idea({ id: IDEAS.fund, name: "A burden-to-funding audit for gallbladder cancer and a dedicated research call", maturity: "speculative", actor: "philanthropy", cost: "small", horizonYears: 3,
    tldr: "Gallbladder cancer has been called scantily understood in 2004 and understudied in 2025 by its own researchers. Counting the money spent on it against the deaths it causes, country by country, would make the gap visible and give funders a target.",
    summary: "The disease is common in Chile, Bolivia, northern India and parts of East Asia and rare in the countries that fund most cancer research; it is treated mostly by surgeons and pooled with cholangiocarcinoma in trials, so it has neither an advocacy base nor a trial portfolio of its own. Successive reviews (Wistuba and Gazdar 2004; Roa 2022; Zhu 2025) describe it as understudied and list the same unmet needs: screening biomarkers, standardised pathology, separate trials. The EULAT Eradicate GBC consortium (EU Horizon 2020) shows what a dedicated call can build. An audit of research spend against disability-adjusted life years, published and repeated, is the cheapest lever, followed by a targeted call from a funder with reach into both high-incidence and high-capacity countries.",
    hypothesis: "Publishing an annual burden-to-funding ratio for gallbladder cancer alongside other gastrointestinal cancers, and pairing it with a dedicated multi-country call, will at least double registered interventional trials naming gallbladder cancer as a primary population within five years.",
    rationale: "Funding follows visibility; the disease's incidental diagnosis and trial pooling have kept it invisible in exactly the systems that allocate research money.",
    test: "Baseline audit using funder databases (NIH RePORTER, UKRI Gateway, Horizon Europe, CRUK) against GLOBOCAN burden; count of interventional trials with gallbladder cancer as primary population on ClinicalTrials.gov before and after a targeted call.",
    cancers: [GB], bottlenecks: ["b-funding-allocation", "b-rare-cancers", "b-incentive-misalignment"], institutions: ["cruk", "nci", "iarc"], keyPapers: ["paper-wistuba-gazdar-gallbladder-cancer-lessons-nat-rev-cancer-2004", "paper-roa-gallbladder-cancer-primer-nat-rev-dis-primers-2022", "paper-zhu-population-specific-immunogenomics-gallbladder-cancer-mod-pathol-2025"], related: ["globocan"],
    links: [epmc("15343276", "Wistuba and Gazdar: gallbladder cancer, lessons from a rare tumour (Nat Rev Cancer 2004)"), epmc("40735836", "Scherer et al.: EULAT Eradicate GBC, the European-Latin American research consortium (Int J Epidemiol 2025)")] }),
];
